Rules.InvariantScript:
Set(gTaxiPositionEdit, false);
// Sortierten Trip-Pool aufbauen (Prioritäts-Algorithmus)
If(!IsBlank(gLoggedInTaxi),
    Set(gTaxiIdx, LookUp(gZoneMap, zone = gLoggedInTaxi.Position, idx));
    ClearCollect(gSortedTrips,
        Sort(
            AddColumns(
                Filter(gTrips,
                    Status = "pending" Or
                    (Status = "accepted"    And TaxiFunkID = gLoggedInTaxi.FunkID) Or
                    (Status = "in_progress" And TaxiFunkID = gLoggedInTaxi.FunkID)
                ),
                "Score",
                If(Status = "pending",
                    Abs(LookUp(gZoneMap, zone = PickupZone, idx) - gTaxiIdx) +
                    Min(LookUp(gZoneMap, zone = PickupZone, idx),
                        11 - LookUp(gZoneMap, zone = PickupZone, idx)) * 0.5 +
                    If((gTaxiIdx <= 4 And LookUp(gZoneMap, zone = PickupZone, idx) <= 4) Or
                       (gTaxiIdx > 4  And LookUp(gZoneMap, zone = PickupZone, idx) > 4),
                       0, 2),
                    -1   // eigene accepted/in_progress Aufträge immer oben
                )
            ),
            Score,
            SortOrder.Ascending
        )
    )
)

If(!IsBlank(gLoggedInTaxi),
    // ❗ Dataverse: ClearCollect(gTrips, PetraTrips)
    Set(gTaxiIdx, LookUp(gZoneMap, zone = gLoggedInTaxi.Position, idx));
    ClearCollect(gSortedTrips,
        Sort(
            AddColumns(
                Filter(gTrips,
                    Status = "pending" Or
                    (Status = "accepted"    And TaxiFunkID = gLoggedInTaxi.FunkID) Or
                    (Status = "in_progress" And TaxiFunkID = gLoggedInTaxi.FunkID)
                ),
                "Score",
                If(Status = "pending",
                    Abs(LookUp(gZoneMap, zone = PickupZone, idx) - gTaxiIdx) +
                    Min(LookUp(gZoneMap, zone = PickupZone, idx), 11 - LookUp(gZoneMap, zone = PickupZone, idx)) * 0.5 +
                    If((gTaxiIdx <= 4 And LookUp(gZoneMap, zone = PickupZone, idx) <= 4) Or
                       (gTaxiIdx > 4  And LookUp(gZoneMap, zone = PickupZone, idx) > 4), 0, 2),
                    -1
                )
            ),
            Score,
            SortOrder.Ascending
        )
    )
)

Set(gLoggedInTaxi, Blank());
Set(gTaxiPositionEdit, false);
Set(gTripToComplete, Blank());
Navigate(SelectRoleScreen, ScreenTransition.Fade)

// ❗ Dataverse: Patch(PetraTaxis, gLoggedInTaxi, {Active: false})
UpdateIf(gTaxis, ID = gLoggedInTaxi.ID, {Active: false});
Set(gLoggedInTaxi, Blank());
Set(gTaxiPositionEdit, false);
Set(gTripToComplete, Blank());
ClearCollect(gSortedTrips, [])

// ❗ Dataverse: Nutze Power Automate Flow "AcceptTrip" für atomare Updates
// Demo: Direkt in Collections aktualisieren
UpdateIf(gTrips, ID = ThisItem.ID And Status = "pending",
    {Status:     "accepted",
     TaxiFunkID: gLoggedInTaxi.FunkID,
     TaxiID:     gLoggedInTaxi.ID,
     TaxiPosition: gLoggedInTaxi.Position});
UpdateIf(gTaxis, ID = gLoggedInTaxi.ID,
    {Occupied: Min(gLoggedInTaxi.Capacity, gLoggedInTaxi.Occupied + ThisItem.Passengers),
     LastSeen: Text(Now(), "hh:mm")});
Set(gLoggedInTaxi, LookUp(gTaxis, ID = gLoggedInTaxi.ID));
// Sortierten Pool neu aufbauen
Set(gTaxiIdx, LookUp(gZoneMap, zone = gLoggedInTaxi.Position, idx));
ClearCollect(gSortedTrips,
    Sort(
        AddColumns(
            Filter(gTrips,
                Status = "pending" Or
                (Status = "accepted"    And TaxiFunkID = gLoggedInTaxi.FunkID) Or
                (Status = "in_progress" And TaxiFunkID = gLoggedInTaxi.FunkID)),
            "Score",
            If(Status = "pending",
                Abs(LookUp(gZoneMap, zone = PickupZone, idx) - gTaxiIdx) +
                Min(LookUp(gZoneMap, zone = PickupZone, idx), 11 - LookUp(gZoneMap, zone = PickupZone, idx)) * 0.5 +
                If((gTaxiIdx <= 4 And LookUp(gZoneMap, zone = PickupZone, idx) <= 4) Or
                   (gTaxiIdx > 4  And LookUp(gZoneMap, zone = PickupZone, idx) > 4), 0, 2),
                -1)
        ),
        Score, SortOrder.Ascending
    )
)

Set(gTaxiNewZone, Left(TaxiPositionDropdown.SelectedText.Value, 1));
UpdateIf(gTaxis, ID = gLoggedInTaxi.ID,
    {Position: gTaxiNewZone,
     LastSeen: Text(Now(), "hh:mm")});
Set(gLoggedInTaxi, LookUp(gTaxis, ID = gLoggedInTaxi.ID));
Set(gTaxiIdx, LookUp(gZoneMap, zone = gTaxiNewZone, idx));
Set(gTaxiPositionEdit, false);
ClearCollect(gSortedTrips,
    Sort(
        AddColumns(
            Filter(gTrips,
                Status = "pending" Or
                (Status = "accepted"    And TaxiFunkID = gLoggedInTaxi.FunkID) Or
                (Status = "in_progress" And TaxiFunkID = gLoggedInTaxi.FunkID)
            ),
            "Score",
            If(Status = "pending",
                Abs(LookUp(gZoneMap, zone = PickupZone, idx) - gTaxiIdx) +
                Min(LookUp(gZoneMap, zone = PickupZone, idx), 11 - LookUp(gZoneMap, zone = PickupZone, idx)) * 0.5 +
                If((gTaxiIdx <= 4 And LookUp(gZoneMap, zone = PickupZone, idx) <= 4) Or
                   (gTaxiIdx > 4  And LookUp(gZoneMap, zone = PickupZone, idx) > 4), 0, 2),
                -1
            )
        ),
        Score,
        SortOrder.Ascending
    )
)

// ❗ Dataverse: Nutze Power Automate Flow "CompleteTrip"
Set(gCompleteZone, Left(CompleteZoneDropdown.SelectedText.Value, 1));
// Trip als abgeschlossen markieren
UpdateIf(gTrips, ID = gTripToComplete.ID,
    {Status: "completed", DropoffZone: gCompleteZone});
// Taxi-Auslastung reduzieren + neue Position setzen
UpdateIf(gTaxis, ID = gLoggedInTaxi.ID,
    {Occupied:  Max(0, gLoggedInTaxi.Occupied - gTripToComplete.Passengers),
     Position:  gCompleteZone,
     LastSeen:  Text(Now(), "hh:mm")});
Set(gLoggedInTaxi, LookUp(gTaxis, ID = gLoggedInTaxi.ID));
Set(gTripToComplete, Blank());
// Sortierten Pool neu aufbauen
Set(gTaxiIdx, LookUp(gZoneMap, zone = gLoggedInTaxi.Position, idx));
ClearCollect(gSortedTrips,
    Sort(
        AddColumns(
            Filter(gTrips,
                Status = "pending" Or
                (Status = "accepted"    And TaxiFunkID = gLoggedInTaxi.FunkID) Or
                (Status = "in_progress" And TaxiFunkID = gLoggedInTaxi.FunkID)),
            "Score",
            If(Status = "pending",
                Abs(LookUp(gZoneMap, zone = PickupZone, idx) - gTaxiIdx) +
                Min(LookUp(gZoneMap, zone = PickupZone, idx), 11 - LookUp(gZoneMap, zone = PickupZone, idx)) * 0.5 +
                If((gTaxiIdx <= 4 And LookUp(gZoneMap, zone = PickupZone, idx) <= 4) Or
                   (gTaxiIdx > 4  And LookUp(gZoneMap, zone = PickupZone, idx) > 4), 0, 2),
                -1)
        ),
        Score, SortOrder.Ascending
    )
)

// Zonen-Kürzel aus Dropdown-Auswahl extrahieren (Format "X – Label")
Set(gLoginZone, Left(LoginZoneDropdown.SelectedText.Value, 1));
Set(gTaxiPositionEdit, false);
Set(gLoginError, "");
// Prüfen ob Funknummer bereits aktiv
If(
    !IsBlank(LookUp(gTaxis, FunkID = Trim(LoginRadioInput.Text) And Active)),
    // Taxi reaktivieren / Position aktualisieren
    UpdateIf(gTaxis, FunkID = Trim(LoginRadioInput.Text),
        {Position: gLoginZone, Active: true, LastSeen: Text(Now(), "hh:mm")}),
    // Neues Taxi anlegen
    Collect(gTaxis, {
        ID:       gNextTaxiID,
        FunkID:   Trim(LoginRadioInput.Text),
        Position: gLoginZone,
        Capacity: 8,
        Occupied: 0,
        Active:   true,
        LastSeen: Text(Now(), "hh:mm")
    });
    Set(gNextTaxiID, gNextTaxiID + 1)
);
Set(gLoggedInTaxi, LookUp(gTaxis, FunkID = Trim(LoginRadioInput.Text)));
// Sortierten Trip-Pool initial aufbauen
Set(gTaxiIdx, LookUp(gZoneMap, zone = gLoggedInTaxi.Position, idx));
ClearCollect(gSortedTrips,
    Sort(
        AddColumns(
            Filter(gTrips, Status = "pending"),
            "Score",
            Abs(LookUp(gZoneMap, zone = PickupZone, idx) - gTaxiIdx) +
            Min(LookUp(gZoneMap, zone = PickupZone, idx), 11 - LookUp(gZoneMap, zone = PickupZone, idx)) * 0.5 +
            If((gTaxiIdx <= 4 And LookUp(gZoneMap, zone = PickupZone, idx) <= 4) Or
               (gTaxiIdx > 4  And LookUp(gZoneMap, zone = PickupZone, idx) > 4), 0, 2)
        ),
        Score, SortOrder.Ascending
    )
)
